typedef struct ConvolverNode {
    AudioNode *audioNode;
    AudioContext *context;
    float sampleRate;
    AudioBus *reverbBus;
    AudioBuffer *buffer;
    pthread_mutex_t bufferMutex;
} ConvolverNode;

ConvolverNode *ConvolverNode_create(AudioContext *context, float sampleRate) {
    ConvolverNode *convolver = (ConvolverNode *)malloc(sizeof(ConvolverNode));
    if (!convolver) return NULL;

    convolver->audioNode = AudioNode_create(context, sampleRate);
    convolver->context = context;
    convolver->sampleRate = sampleRate;
    convolver->reverbBus = NULL;
    convolver->buffer = NULL;
    pthread_mutex_init(&convolver->bufferMutex, NULL);

    return convolver;
}

void ConvolverNode_process(ConvolverNode *self, float **input, float **output, int frames) {
    if (!self || !input || !output || frames <= 0) {
        // Output silence if not initialized or reverb not set
        for (int i = 0; i < frames; i++) {
            output[i][0] = 0.0f;
            output[i][1] = 0.0f;
        }
        return;
    }

    pthread_mutex_lock(&self->bufferMutex);
    if (self->reverbBus) {
        reverb_engine_process(input, output, frames);
    } else {
        for (int i = 0; i < frames; i++) {
            output[i][0] = 0.0f;
            output[i][1] = 0.0f;
        }
    }
    pthread_mutex_unlock(&self->bufferMutex);
}

void ConvolverNode_setBuffer(ConvolverNode *self, AudioBuffer *buffer) {
    if (!self || !buffer) {
        return;
    }

    pthread_mutex_lock(&self->bufferMutex);
    if (self->reverbBus) {
        AudioBus_release(self->reverbBus);
    }

    AudioBus *bus = AudioBus_wrap(buffer);
    if (bus) {
        self->reverbBus = bus;
    }
    self->buffer = buffer;
    pthread_mutex_unlock(&self->bufferMutex);
}

AudioBuffer *ConvolverNode_getBuffer(ConvolverNode *self) {
    if (!self) return NULL;

    return self->buffer;
}

float ConvolverNode_getTailTime(ConvolverNode *self) {
    if (!self || !self->buffer) return 0.0f;

    return calculateTailTime(self->buffer);
}

float ConvolverNode_getLatencyTime(ConvolverNode *self) {
    if (!self || !self->buffer) return 0.0f;

    return calculateLatencyTime(self->buffer);
}

void ConvolverNode_destroy(ConvolverNode *self) {
