    node->sampleRate = sampleRate;
    node->impulseResponseBuffer = NULL;
    node->reverb = NULL;
    Mutex_init(&node->mutex);
}

void ConvolverNode_process(ConvolverNode* node, AudioFrame* input, AudioFrame* output, int frames) {
    if (!node || !node->reverb) {
        for (int i = 0; i < frames; i++) {
            for (int ch = 0; ch < output->channelCount; ch++) {
                output->data[ch][i] = 0.0;
            }
        }
        return;
    }

    Mutex_lock(&node->mutex);
    reverb_process(node->reverb, input, output, frames);
    Mutex_unlock(&node->mutex);
}

