    if (!node || !buffer) {
        node->impulseResponseBuffer = NULL;
        node->reverb = NULL;
        return;
    }

    if (!AudioBuffer_isValid(buffer)) {
        node->impulseResponseBuffer = NULL;
        node->reverb = NULL;
        return;
    }

    node->impulseResponseBuffer = buffer;
    node->reverb = createReverbFromBuffer(buffer, node->sampleRate);
}

